Literal.Value:
'{
  "$schema": "https://vega.github.io/schema/vega/v5.json",
  "description": "Poznamky card - PoznamkaPc + PoznamkaProjekce, both with header+body, labels centered above",
  "padding": 0,
  "background": "#ffffff",
  "signals": [
    {"name": "W", "update": "pbiContainer.width"},
    {"name": "lineH",  "value": 14},
    {"name": "labelH", "value": 12},
    {"name": "rowPad", "value": 8},
    {"name": "gapH",   "value": 18},
    {"name": "topPad", "value": 14},
    {"name": "headerBodyGap", "value": 14},
    {"name": "chunkSize", "update": "max(20, floor((W - 24) / 7))"},

    {"name": "s1HeaderLines", "update": "length(data(''active'')) ? length(data(''active'')[0].PcHeaderArr) : 1"},
    {"name": "s1BodyLines",   "update": "length(data(''active'')) ? length(data(''active'')[0].PcBodyArr) : 1"},
    {"name": "s2HeaderLines", "update": "length(data(''active'')) ? length(data(''active'')[0].ProjekceHeaderArr) : 1"},
    {"name": "s2BodyLines",   "update": "length(data(''active'')) ? length(data(''active'')[0].ProjekceBodyArr) : 1"},

    {"name": "r1H", "update": "max(110, s1HeaderLines * lineH + headerBodyGap + s1BodyLines * lineH + rowPad*2)"},
    {"name": "r2H", "update": "max(110, s2HeaderLines * lineH + headerBodyGap + s2BodyLines * lineH + rowPad*2)"},

    {"name": "contentH", "update": "topPad + r1H + gapH + r2H + 8"},
    {"name": "H", "update": "max(pbiContainer.height, contentH)"},

    {"name": "r1Y", "update": "topPad"},
    {"name": "r2Y", "update": "topPad + r1H + gapH"},

    {"name": "bodyY",  "update": "r1Y + 4 + s1HeaderLines * lineH + headerBodyGap"},
    {"name": "body2Y", "update": "r2Y + 4 + s2HeaderLines * lineH + headerBodyGap"}
  ],
  "width":  {"signal": "W"},
  "height": {"signal": "H"},
  "data": [
    {"name": "dataset"},
    {
      "name": "active",
      "source": "dataset",
      "transform": [
        {"type": "filter", "expr": "datum[''HasOneProject''] == 1"},

        {"type": "formula", "as": "PcParts",       "expr": "split(datum.PoznamkaPc, ''<<HDR>>'')"},
        {"type": "formula", "as": "ProjekceParts", "expr": "split(datum.PoznamkaProjekce, ''<<HDR>>'')"},

        {"type": "formula", "as": "PcHeaderArr",
         "expr": "split(replace(datum.PcParts[0], /\\r?\\n|\\\\n|\\|\\|\\|/g, ''\\n''), ''\\n'')"},
        {"type": "formula", "as": "PcBodyArr",
         "expr": "split(replace(replace(replace(datum.PcParts[1], /\\r?\\n|\\\\n|\\|\\|\\|/g, ''\\n''), regexp(''([^\\n]{1,'' + chunkSize + ''})( |\\n)'', ''g''), ''$1\\n''), regexp(''([^\\n]{'' + chunkSize + ''})(?=[^\\n])'', ''g''), ''$1\\n''), ''\\n'')"},

        {"type": "formula", "as": "ProjekceHeaderArr",
         "expr": "split(replace(datum.ProjekceParts[0], /\\r?\\n|\\\\n|\\|\\|\\|/g, ''\\n''), ''\\n'')"},
        {"type": "formula", "as": "ProjekceBodyArr",
         "expr": "split(replace(replace(replace(datum.ProjekceParts[1], /\\r?\\n|\\\\n|\\|\\|\\|/g, ''\\n''), regexp(''([^\\n]{1,'' + chunkSize + ''})( |\\n)'', ''g''), ''$1\\n''), regexp(''([^\\n]{'' + chunkSize + ''})(?=[^\\n])'', ''g''), ''$1\\n''), ''\\n'')"}
      ]
    },
    {
      "name": "inactive",
      "source": "dataset",
      "transform": [{"type": "filter", "expr": "datum[''HasOneProject''] == 0"}]
    }
  ],
  "marks": [
    {
      "type": "text", "from": {"data": "inactive"},
      "encode": {
        "enter": {"text": {"value": "Zvol Projekt"}, "fontSize": {"value": 16}, "fontWeight": {"value": "bold"}, "fill": {"value": "#31028C"}, "align": {"value": "center"}, "baseline": {"value": "middle"}},
        "update": {"x": {"signal": "W / 2"}, "y": {"signal": "pbiContainer.height / 2"}}
      }
    },

    {"type": "text", "from": {"data": "active"}, "encode": {"update": {
      "x": {"signal": "W / 2"}, "y": {"signal": "r1Y - 2"},
      "text": {"value": "Poznámka Projektového Koordinátora na Projektu"},
      "fontSize": {"value": 9}, "fill": {"value": "#A0A0A0"},
      "align": {"value": "center"}, "baseline": {"value": "bottom"}
    }}},
    {"type": "rect", "from": {"data": "active"}, "encode": {"update": {
      "x": {"value": 0}, "width": {"signal": "W"},
      "y": {"signal": "r1Y"}, "height": {"signal": "r1H"},
      "fill": {"value": "#E4F5FB"}, "cornerRadius": {"value": 6}
    }}},
    {"type": "text", "from": {"data": "active"}, "encode": {"update": {
      "x": {"value": 8}, "y": {"signal": "r1Y + 4"},
      "text": {"field": "PcHeaderArr"}, "fontSize": {"value": 12}, "fontWeight": {"value": "bold"},
      "fill": {"value": "#31028C"}, "align": {"value": "left"}, "baseline": {"value": "top"},
      "lineHeight": {"signal": "lineH"}
    }}},
    {"type": "text", "from": {"data": "active"}, "encode": {"update": {
      "x": {"value": 8}, "y": {"signal": "bodyY"},
      "text": {"field": "PcBodyArr"}, "fontSize": {"value": 12}, "fontWeight": {"value": "bold"},
      "fill": {"value": "#31028C"}, "align": {"value": "left"}, "baseline": {"value": "top"},
      "lineHeight": {"signal": "lineH"}, "tooltip": {"field": "PoznamkaPc"}
    }}},

    {"type": "text", "from": {"data": "active"}, "encode": {"update": {
      "x": {"signal": "W / 2"}, "y": {"signal": "r2Y - 2"},
      "text": {"value": "Poznámka Projektového Koordinátora v Projekci"},
      "fontSize": {"value": 9}, "fill": {"value": "#A0A0A0"},
      "align": {"value": "center"}, "baseline": {"value": "bottom"}
    }}},
    {"type": "rect", "from": {"data": "active"}, "encode": {"update": {
      "x": {"value": 0}, "width": {"signal": "W"},
      "y": {"signal": "r2Y"}, "height": {"signal": "r2H"},
      "fill": {"value": "#E4F5FB"}, "cornerRadius": {"value": 6}
    }}},
    {"type": "text", "from": {"data": "active"}, "encode": {"update": {
      "x": {"value": 8}, "y": {"signal": "r2Y + 4"},
      "text": {"field": "ProjekceHeaderArr"}, "fontSize": {"value": 12}, "fontWeight": {"value": "bold"},
      "fill": {"value": "#31028C"}, "align": {"value": "left"}, "baseline": {"value": "top"},
      "lineHeight": {"signal": "lineH"}
    }}},
    {"type": "text", "from": {"data": "active"}, "encode": {"update": {
      "x": {"value": 8}, "y": {"signal": "body2Y"},
      "text": {"field": "ProjekceBodyArr"}, "fontSize": {"value": 12}, "fontWeight": {"value": "bold"},
      "fill": {"value": "#31028C"}, "align": {"value": "left"}, "baseline": {"value": "top"},
      "lineHeight": {"signal": "lineH"}, "tooltip": {"field": "PoznamkaProjekce"}
    }}}
  ]
}'
